/* ============================================================================
 * C0/8A6D  auto_walk_dispatch()  (DP=$1D00; entered with A 8-bit, X/Y 8-bit)
 * Called from C0/881E at 8847 only when $0120 != 0 (8845 SEP #$10; 884A REP #$10).
 * A-WIDTH CONFIRMED 8-bit at entry (trace: m=1 at PC 8847/8A6D), so LDA $30/$2E
 * read ONLY the low byte and BEQ/BMI test the low byte's value/sign. In free-roam
 * $2E==$30==0 here (runs BEFORE 91AC builds velocity) -> always 8A8E RTS (trace:
 * 0 hits on every deep handler). Handlers fire only when a script pre-seeds vel.
 * ==========================================================================*/
void auto_walk_dispatch(void) {            // 8A6D
    int8 vy = (int8)$30;                    // 8A6D LDA $30  (8-bit low byte)
    if (vy == 0) {                          // 8A6F BEQ 8A82
        int8 vx = (int8)$2E;                // 8A82 LDA $2E
        if (vx == 0) return;                // 8A84 BEQ 8A8E -> 8A8E RTS  (FREE-ROAM path)
        if (vx < 0)  h_8BC4_west();         // 8A8B BRL 8BC4   (X<0,Y=0: WEST)
        else         h_8AB5_east();         // 8A88 BRL 8AB5   (X>0,Y=0: EAST)
        return;
    }
    if (vy < 0) {                           // 8A71 BMI 8A8F  (Y<0: NORTH group)
        int8 vx = (int8)$2E;                // 8A8F LDA $2E
        if (vx == 0) h_8BF9_north();        // 8A9B BRL 8BF9   (X=0,Y<0: NORTH/up)
        else if (vx < 0) h_8EF1_nw();       // 8A98 BRL 8EF1   (X<0,Y<0: NW)
        else             h_8E21_ne();       // 8A95 BRL 8E21   (X>0,Y<0: NE)
    } else {                                // (Y>0: SOUTH group, 8A73)
        int8 vx = (int8)$2E;                // 8A73 LDA $2E
        if (vx == 0) h_8D11_south();        // 8A7F BRL 8D11   (X=0,Y>0: SOUTH/down)
        else if (vx < 0) h_8FC1_sw();       // 8A7C BRL 8FC1   (X<0,Y>0: SW)
        else             h_909C_se();       // 8A79 BRL 909C   (X>0,Y>0: SE)
    }
}

/* ----------------------------------------------------------------------------
 * C0/8A9E  probe_tile_solid()  -> A=1 solid/off-map, A=0 passable. DUAL SIGNAL.
 *   ($66/$67 = tentative X word/high, $68 = tentative Y word.)
 * --------------------------------------------------------------------------*/
uint8 probe_tile_solid(void) {             // 8A9E
    A16 = $68;                              // 8A9E LDA $68 (tentative Y, 16-bit in)
    SEP_A8(); A8 = $67;                     // 8AA0/8AA2  (tentative X high byte)
    if (prop_fetch_off_map(&A)) {           // 8AA4 JSR 9AA1 ; 8AA7 BCC 8AAC
        /* 9AA1: REP#$20; A&=$1E -> X; if $7E70C0[X] bit7 set -> SEC (off map) */
        return 1;                           // 8AA9 LDA #$01 ; 8AAB RTS  (carry SET)
    }
    prop_fetch_full();                      // 8AAC JSR 9AD3  (decode shape+z -> $58/$5A/$5C/$6A/$6C)
    zgate();                                // 8AAF JSR 9C37  (z-gate -> sets carry)
    return 0;                               // 8AB2 LDA #$00 ; 8AB4 RTS  (carry = z-gate)
}
/* Handlers branch on BOTH A (BNE/BEQ) and carry (BCS/BCC): A==1 => off-map,
 * carry SET; A==0 => carry = z-gate verdict. (Confirmed against 9AA1/9C37.) */

/* ----------------------------------------------------------------------------
 * C0/9923  probe_actor_block()  -> carry SET = blocked. (Verified.)
 *   LDA $7F2000; ASL;TAX loop. skip if $0F00,X==0, $1100,X bit7 set, or
 *   X==$0197/$0199/$019B. test $1B01,X BIT #$01:
 *     bit0 SET  -> branch 9960: hit returns SEC (9989)
 *     bit0 CLR  -> branch 99A1: hit returns CLC (99CA)
 *   hit test: |$1880,X-$68| < $00E0 AND |$1800,X-$66| < $00E0 (CMP#$E0;BCS reject)
 *   writes $01EB scratch (#$0080 / STX), restores X 16-bit on exit.
 * --------------------------------------------------------------------------*/
bool probe_actor_block(void);              // 9923

/* ----------------------------------------------------------------------------
 * Directional handler skeleton (X=$0197 player; base $1800,X->$62, $1880,X->$64;
 * tentative point in $66/$68; $70=112 feeler radius, $40=64 foot offset).
 * Sign bytes: $2F = X high (0 for E/S/N/down/SE/NE; $FF for W/NW/SW),
 *             $31 = Y high (0 for E/S/SE/SW/down; $FF for N/NE/NW/up).
 * --------------------------------------------------------------------------*/
void h_8AB5_east(void){                     // EAST (X>0,Y=0)
    $2F=0; $31=0;                           // 8AB5/8AB7
    X=$0197; $62=$1800,X;                   // 8AB9/8ABE
    $66 = $62 + 0x0070 + $2E;               // 8AC4 ADC#$70 ; 8AC7 ADC $2E
    $64=$1880,X; $68 = $64 - 0x0040;        // 8ACB/8AD1 upper foot
    if (probe_actor_block()) { $2E=0; return; }      // 8AD8/8ADB BCC 8AE4
    /* ---- shared mid-section, also reached by WEST via BRL 8AE4 ---- */
mid_8AE4:
    $68 = $64;                              // 8AE6 mid feeler
    if (probe_tile_solid()) {               // 8AEA JSR 8A9E ; 8AED BCS 8B02
        if (A != 0) { $2E=0; return; }      // 8B02 BNE 8B13 -> STZ $2E; RTS (off-map)
        /* z-solid (A==0,carry set): try lower foot, slide */
        $68 = $64 - 0x0070;                 // 8B04-8B0C
        if (probe_tile_solid()) { $2E=0; return; }    // 8B0E/8B11 BCC 8B1A
        $30 = 0xFFF0 (-16); $68 = $64 + $30;          // 8B1C/8B22 slide up
        if (probe_tile_solid()) {           // 8B26
            if (A==0 && carry) goto slide_8B7E;       // 8B2B BRA 8B7E
            /* A!=0 -> 8B13 STZ $2E; RTS */
            $2E=0; return;                  // 8B2D BNE 8B13
        }
        $68 = $64 - 0x0070 + $30;           // 8B31-8B3A
        if (probe_tile_solid()) { $2E=0; $30=0; return; }  // 8B3C/8B3F
        commit_9C5C();                      // 8B4A BRL 9C5C
    } else {
        $68 = $64 - 0x0070;                 // 8AF1 upper foot
        if (probe_tile_solid()) goto slide_8B4D;       // 8AF9/8AFC BCS 8B4D (+16 slide, mirror of 8B1A)
        commit_9C5C(); return;              // 8AFE JSR 9C5C ; 8B01 RTS  (CLEAR: commit)
    }
}
